 for(const [kind,arr,type]of [['reading',readings,'r'],['listening',listenings,'l']]){const t=u[kind];t.ids=[t.id];more[kind].forEach(([q,options,why],i)=>{const choices=options.split('|'),shift=(ui+i+1)%choices.length;const id=t.id+'-extra'+(i+1);arr.push({id,level:'N4',type,title:u.title,text:t.text,translation:t.translation,q,options:[...choices.slice(shift),...choices.slice(0,shift)],answer:(choices.length-shift)%choices.length,why,unit:u.id});t.ids.push(id);});}
